The investigation supports two independent root causes, both reaching users through `ts-ui-dashboard` and `ts-preserve-service`.

```json
{
  "root_causes": [
    {
      "service": "ts-consign-service",
      "fault_kind": "process_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT p, round(avg(value),3) cpu_usage, round(max(value),3) cpu_max, count(*) n FROM (SELECT 'n' p, * FROM normal_metrics UNION ALL SELECT 'a', * FROM abnormal_metrics) WHERE metric='container.cpu.usage' AND service_name='ts-consign-service' GROUP BY 1", "claim": "ts-consign-service container CPU rises from about 0.07 to 0.61 cores, while the pod stays well below its limit."},
        {"kind": "trace", "sql": "SELECT p, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) WHERE service_name='ts-consign-service' AND span_name IN ('ConsignController.findByOrderId','ConsignRepository.findByOrderId','SELECT ConsignRecord','SELECT ts.consign_record') GROUP BY 1,2 ORDER BY 2,1", "claim": "Consign in-process controller and repository time grows sharply while the JDBC SELECT stays around 1 ms, so time is burned inside the process."}
      ]
    },
    {
      "service": "ts-food-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "WITH t AS (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces), c AS (SELECT p, trace_id, span_id, service_name csvc, duration::DOUBLE cdur FROM t WHERE attr_span_kind='Client' AND span_name NOT LIKE 'SELECT%' AND span_name NOT LIKE 'INSERT%' AND span_name NOT LIKE 'UPDATE%'), s AS (SELECT p, trace_id, parent_span_id, service_name ssvc, duration::DOUBLE sdur FROM t WHERE attr_span_kind='Server'), g AS (SELECT c.p, c.csvc, s.ssvc, (c.cdur-s.sdur)/1e6 gap FROM c JOIN s ON c.p=s.p AND c.trace_id=s.trace_id AND c.span_id=s.parent_span_id WHERE c.csvc='ts-food-service') SELECT ssvc, p, count(*) n, round(quantile_cont(gap,0.5),1) p50_gap_ms, round(quantile_cont(gap,0.9),1) p90_gap_ms FROM g GROUP BY 1,2 ORDER BY 1,2", "claim": "Food-service outgoing calls keep normal medians but p90 wire/HTTP gap jumps (e.g. to travel 3.5→65 ms, station 4.4→35 ms)."},
        {"kind": "trace", "sql": "WITH t AS (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) SELECT c.p, c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) caller_client_ms, round(avg(s.duration)/1e6,1) callee_server_ms FROM t c JOIN t s ON s.p=c.p AND s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-preserve-service' AND s.service_name='ts-food-service' GROUP BY ALL ORDER BY 1", "claim": "Preserve's calls to food-service go from about 17 ms to 222 ms, with the food server span holding most of it."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-consign-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "WITH t AS (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) SELECT c.p, c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) caller_ms, round(avg(s.duration)/1e6,1) consign_server_ms FROM t c JOIN t s ON s.p=c.p AND s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-consign-service' AND s.attr_span_kind='Server' GROUP BY ALL ORDER BY 1", "claim": "Consign-service server time for consign endpoints rises from about 9 ms to about 46–384 ms as seen from ui-dashboard."}]},
    {"from": "ts-food-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, attr_span_kind k, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE span_name LIKE 'GET /api/v1/foodservice/foods/%' AND service_name IN ('ts-ui-dashboard','ts-food-service') GROUP BY 1,2,3 ORDER BY 3,1", "claim": "The user-facing foods endpoints on ui-dashboard slow down in step with the slower food-service server spans."}]},
    {"from": "ts-food-service", "to": "ts-preserve-service", "evidence": [{"kind": "trace", "sql": "WITH t AS (SELECT 'n' p, * FROM normal_traces UNION ALL SELECT 'a', * FROM abnormal_traces) SELECT c.p, c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) caller_client_ms, round(avg(s.duration)/1e6,1) callee_server_ms FROM t c JOIN t s ON s.p=c.p AND s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-preserve-service' AND s.service_name='ts-food-service' GROUP BY ALL ORDER BY 1", "claim": "Preserve's POST to food-service rises from about 17 ms to 222 ms, so preserve requests slow down."}]}
  ]
}
```
